insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('1', '2026-07-10 17:28:04.180767+00', 'true', 'CAT_RISK_THRESHOLD', 'The minimum proportion of maximum possible score at which a category is flagged as a primary problem area for this founder. When a category''s accumulated risk score reaches or exceeds 30% of its maximum possible score, the branching logic switches to deep-dive mode for that category — skipping remaining Supplementary questions and firing targeted root cause confirmation probes instead. Set deliberately conservative at 30% so that diagnostic signal is detected early, well before total category failure. This threshold should be calibrated against real session data post-launch: if 30% produces too many false positives, raise it; if real issues are being missed, lower it. Applied independently to each of the 8 diagnostic categories using the per-category maximum scores, which must be computed per session — see CATEGORY_MAX_COMPUTED_PER_SESSION.', 'Category Risk Threshold', '0.3000', 'Category-Level Aggregation', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('2', '2026-07-10 17:28:04.180767+00', 'true', 'CONFIRMED_MULTIPLIER', 'The weight multiplier applied to a root cause hypothesis when it has been Confirmed through the adaptive branching logic. A root cause is marked Confirmed when the original question scores 2 (Red) AND the immediately following single follow-up probe also scores 2 (Red). This double-red pattern indicates the founder gave a high-risk answer and then gave a second high-risk answer when probed more specifically — making it significantly more likely that this root cause is genuinely active rather than a false positive triggered by a poorly worded answer or an unusual framing. The 1.5x multiplier is applied in the final root cause ranking formula, increasing the confirmed root cause''s overall weighted score by 50% relative to an unconfirmed one. Confirmed root causes are strong candidates for the top 3 that drive the Founder Clarity Report''s next steps.', 'Confirmed Root Cause Weight Multiplier', '1.5000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('3', '2026-07-10 17:28:04.180767+00', 'true', 'UNCONFIRMED_MULTIPLIER', 'The weight multiplier applied to a root cause hypothesis that was detected via a Score 2 (Red) on the original question but then partially or fully resolved when the follow-up probe scored 0 or 1. This pattern suggests the original red flag may have been a false positive — either the question was ambiguous, the founder misunderstood it, or the follow-up probe revealed the founder actually has more clarity than the first answer suggested. The root cause remains in the ranking at its base probability weight (no amplification, no suppression) and is retained as a secondary consideration in the Founder Clarity Report rather than a confirmed finding. Unconfirmed root causes should not drive the primary next-step recommendations but may appear as supporting context.', 'Unconfirmed Root Cause Weight Multiplier', '1.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('4', '2026-07-10 17:28:04.180767+00', 'true', 'NOT_TESTED_MULTIPLIER', 'The weight multiplier applied to root cause hypotheses that were never directly probed during the session — either because the relevant category was skipped via the adaptive branching logic, the founder ran out of session time before those questions were reached, or the question was Supplementary and was dropped when the category entered deep-dive mode. A Not Tested root cause cannot be confirmed or denied — it exists only as a theoretical possibility based on stage and industry probability weights. The 0.5x multiplier reduces its influence in the final ranking to ensure that session-tested root causes with real answer data take precedence. Not Tested root causes may still appear in the report under a clearly labelled ''areas to explore'' section distinct from the confirmed findings.', 'Not Tested Root Cause Weight Multiplier', '0.5000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('5', '2026-07-10 17:28:04.180767+00', 'true', 'QUESTION_SCORE_GREEN', 'The numerical score assigned when a founder''s answer demonstrates clear evidence, specificity, and ownership. A Green answer means the founder can cite concrete data, named customers, specific metrics, or measurable outcomes that directly address what the question probes. Examples: ''We interviewed 40 potential customers, 28 said they would pay, and we have 12 paying pilot customers right now'' is a Score 0 Green answer to a customer validation question. A Green score contributes 0 to the category risk accumulation and does not trigger any follow-up probe. Green answers across multiple questions in a category are a positive signal that the founder has genuine clarity in that area — this should be surfaced in the report as a strength, not just the absence of a problem.', 'Question Score — Green (Low Risk)', '0.0000', 'Question-Level Scoring Schema', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('6', '2026-07-10 17:28:04.180767+00', 'true', 'QUESTION_SCORE_AMBER', 'The numerical score assigned when a founder''s answer shows partial evidence or reasoning but lacks specificity, recency, or a complete picture. Amber answers contain some hedging, generalisation, or vagueness — the founder is not completely without knowledge but cannot demonstrate the depth or concreteness that a Green answer would require. Example: ''We talked to a few people early on and they seemed interested'' is a Score 1 Amber answer to a customer validation question. A single Amber score does not trigger a follow-up probe. However, 2 or more Amber scores within the same category trigger a category-level clarifying question that asks the founder to self-assess that category directly — either escalating the pattern to Red or resolving it. Amber scores accumulate toward the CAT_RISK_THRESHOLD alongside Red scores.', 'Question Score — Amber (Moderate Risk)', '1.0000', 'Question-Level Scoring Schema', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('7', '2026-07-10 17:28:04.180767+00', 'true', 'QUESTION_SCORE_RED', 'The numerical score assigned when a founder''s answer reveals no real evidence, relies on assumption or founder belief alone, or actively avoids the question. A Red answer means the founder cannot demonstrate the capability, clarity, or evidence that the question probes — and the red_flag_pattern column in the questions table is the reference for what constitutes a Score 2 answer per question. Example: ''I just know this is something people need — I have seen the problem myself'' is a Score 2 Red answer to a customer validation question. Every Red score immediately triggers the single-question branching rule: one follow-up probe fires targeting the specific root cause hypothesis suggested by that red flag answer. If the founder''s answer is ambiguous between Amber and Red, the Agent defaults to Red and fires a clarifying follow-up rather than guessing.', 'Question Score — Red (High Risk)', '2.0000', 'Question-Level Scoring Schema', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('8', '2026-07-10 17:28:04.180767+00', 'true', 'DISTRESS_SCORE_RED', 'The score threshold at which a Distress-Tagged question in Category 8 (Founder Psychology) triggers the Distress Protocol rather than the standard branching logic. Distress-Tagged questions are a subset of Category 8 whose Red Flag Answers overlap with the Acute Distress Signals defined in the session_state_bands table State D — specifically questions probing fear of failure, sustained isolation, identity collapse, hopelessness, and sustained physical neglect. When any single Distress-Tagged question scores 2 (Red), the standard scoring and branching logic is immediately paused. No standard follow-up probe fires. Instead, the matching empathy protocol in prompt_library where category = distress is applied before the session continues. This is a complete override of the standard branching rule — distress detection takes priority over diagnostic completeness without exception.', 'Distress Question Score — Red Trigger', '2.0000', 'Founder Psychology Distress Protocol', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('9', '2026-07-10 17:28:04.180767+00', 'true', 'DISTRESS_QUESTIONS_TRIGGER', 'The minimum number of Distress-Tagged questions that must score 2 (Red) within a single session to activate full Distress Mode. When this threshold is reached, all other category branching rules are overridden. The session moves into Distress Mode: remaining Category 8 questions continue to be asked with maximum care and warmth per the question bank guidance, but no further questions from other diagnostic categories are introduced until the founder''s emotional state has been explicitly checked per the the session_state_bands table closing protocol. The Founder Clarity Report is then restructured per the High Distress Session State rules in the session_state_bands table — leading with acknowledgement, including a support-related recommendation before any business recommendation, and explicitly offering the option to continue the diagnostic in a follow-up session. Wellbeing overrides diagnostic completeness in all cases.', 'Distress Mode Activation Threshold', '2.0000', 'Founder Psychology Distress Protocol', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('10', '2026-07-10 17:28:04.180767+00', 'true', 'SESSION_STATE_HIGH_DISTRESS_THRESHOLD', 'The minimum cumulative session-level distress score from the psychological_state_signals and session_state_bands tables at which the session is classified as High Distress state. This score is calculated separately from the category risk scores and aggregates signals from the founder''s language patterns, response pace, tone, and answers to distress-adjacent questions throughout the session — not only from Category 8 questions. When the session-level distress score reaches or exceeds 36.0, the system flags this session as High Distress regardless of the standard category scoring outcomes. This flag changes the report structure, the closing protocol, and the recommended next steps. It also cross-references the DISTRESS_QUESTIONS_TRIGGER rule — if the session distress score exceeds this threshold but fewer than 2 distress questions have scored Red, the Agent should proactively check in on the founder''s state before proceeding.', 'Session State High Distress Score Threshold', '36.0000', 'Psychological State Scoring Table', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('11', '2026-07-10 17:28:04.180767+00', 'true', 'WEIGHT_CATEGORY_RISK', 'The weight assigned to the normalised Category Risk Score in the final root cause ranking formula that produces the Founder Clarity Report. The Category Risk Score is the proportion of maximum possible score accumulated within each category during the session — normalised to a 0.0 to 1.0 scale for comparability across categories with different question counts. At 40% this is the highest weighted factor in the ranking formula, reflecting the principle that a root cause detected through direct questioning and real answer scoring is more reliable than probabilistic inference alone. A root cause that lives in a high-scoring category will outrank a root cause with the same base probability that lives in a low-scoring category. All four ranking weights must sum to exactly 1.0 — see WEIGHT_FACTORS_SUM_CHECK.', 'Final Ranking Weight — Category Risk Score', '0.4000', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('12', '2026-07-10 17:28:04.180767+00', 'true', 'WEIGHT_CONFIRMATION_STATUS', 'The weight assigned to the root cause confirmation status multiplier in the final root cause ranking formula. Confirmation status reflects whether the root cause hypothesis was Confirmed (1.5x via double-Red pattern), Unconfirmed (1.0x via Red then improvement on follow-up), or Not Tested (0.5x via no direct probe). At 25% this is the second-highest weighted factor, reflecting the significant diagnostic value of the adaptive branching confirmation pattern. A Confirmed root cause with a 1.5x multiplier on a 25% weight factor gains a substantial advantage over an Unconfirmed competitor with a 1.0x multiplier, all else being equal. This weight incentivises the Agent to surface the most diagnostically confident root causes — those where two direct probes both pointed in the same direction — as the primary findings.', 'Final Ranking Weight — Root Cause Confirmation Status', '0.2500', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('13', '2026-07-10 17:28:04.180767+00', 'true', 'WEIGHT_STAGE_PROBABILITY', 'The weight assigned to the stage-adjusted root cause probability in the final root cause ranking formula. This probability comes from the root_cause_weights table which defines how likely each root cause is to be active at each of the 8 founder stages. A root cause that is statistically common at Stage 3 (Prototype/MVP) will receive a higher base probability for a Stage 3 founder than the same root cause would receive for a Stage 6 (Expansion) founder. At 20% this is the third-highest weighted factor — meaningful but subordinate to direct session evidence (Category Risk and Confirmation Status). Stage probability is the prior that gets updated by the session evidence. When a founder''s session evidence strongly contradicts the stage prior, the session evidence wins.', 'Final Ranking Weight — Stage-Adjusted Probability', '0.2000', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('14', '2026-07-10 17:28:04.180767+00', 'true', 'WEIGHT_INDUSTRY_PROBABILITY', 'The weight assigned to the industry-adjusted root cause probability in the final root cause ranking formula. This probability comes from the industries table which defines how likely each root cause is to be active for founders in each of the 4 industry verticals — SaaS, Services, Manufacturing/D2C, and NGO. A root cause that is categorised as CRITICAL weight for SaaS founders (such as high churn) will receive a higher industry probability boost for a SaaS founder than for a manufacturing founder presenting the same symptoms. At 15% this is the lowest weighted factor in the ranking formula, reflecting the principle that industry context calibrates but does not override direct evidence. When the founder''s answers tell a clear story, industry probability is a refinement — not a determinant.', 'Final Ranking Weight — Industry-Adjusted Probability', '0.1500', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('15', '2026-07-10 17:28:04.180767+00', 'true', 'AMBER_CLUSTER_TRIGGER', 'The minimum number of Amber (Score 1) answers within a single diagnostic category that triggers a category-level clarifying question — even when no Red scores are present in that category. When 2 or more questions in the same category each score 1 (Amber) with no Red scores present, a single category-level clarifying question fires: the founder is asked to self-assess that category directly, for example ''On a scale of confidence, how sure are you that this area of your business is working well right now?'' This self-assessment either escalates the amber pattern to Red — triggering the standard branching logic — or resolves it as a false cluster with no further follow-up. The Amber Cluster rule prevents a pattern of multiple partial-evidence answers from being dismissed just because no single answer crosses the Red threshold.', 'Amber Cluster Follow-Up Trigger', '2.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('16', '2026-07-10 17:28:04.180767+00', 'true', 'MULTI_CATEGORY_FLAG_THRESHOLD', 'The minimum number of categories simultaneously flagged as primary issue areas (each crossing CAT_RISK_THRESHOLD) that triggers a mandatory cross-check against the founder''s Psychological State Score before the report is finalised. When 3 or more categories are flagged simultaneously, this pattern suggests one of two explanations: either the founder is genuinely at an early stage where everything is unresolved (Stage 1 or 2, where broad low-scoring is expected and normal), or the founder is in high distress and scoring poorly across the board because their psychological state is degrading their answers rather than because every business area is genuinely broken. The Agent must cross-check against the Session State distress score and the founder''s stage before concluding that every flagged category represents a distinct real problem. If Session State is Significantly Guarded or High Distress, the report should note that re-assessment after a follow-up conversation may produce a clearer picture.', 'Multi-Category Flag Distress Cross-Check Threshold', '3.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('17', '2026-07-10 17:28:04.180767+00', 'true', 'TOP_ROOT_CAUSES_REPORT', 'The number of root causes selected from the final weighted ranking to drive the Founder Clarity Report''s crystal-clear next steps. After the full ranking formula is applied (combining WEIGHT_CATEGORY_RISK, WEIGHT_CONFIRMATION_STATUS, WEIGHT_STAGE_PROBABILITY, and WEIGHT_INDUSTRY_PROBABILITY), the top 3 root causes by final weighted score become the basis for the report''s three recommended next steps, drawn from the interventions table. Three was chosen deliberately — more than two creates meaningful diagnostic specificity, fewer than four avoids overwhelming the founder with competing priorities. If Distress Mode was triggered during the session, this ranking is still calculated but the presentation order in the report is overridden: the distress-related findings are surfaced first, and the business root causes follow only after the acknowledgement and support-related recommendations.', 'Top Root Causes Surfaced in Founder Clarity Report', '3.0000', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('18', '2026-07-10 17:28:04.180767+00', 'true', 'WEIGHT_FACTORS_SUM_CHECK', 'A system integrity check value confirming that the four ranking weight factors in the final root cause formula sum to exactly 1.0. WEIGHT_CATEGORY_RISK (0.40) + WEIGHT_CONFIRMATION_STATUS (0.25) + WEIGHT_STAGE_PROBABILITY (0.20) + WEIGHT_INDUSTRY_PROBABILITY (0.15) = 1.00. The backend scoring engine should validate this sum on startup and throw a configuration error if any weight is updated without the others being adjusted to maintain this constraint — otherwise the final scores will be incorrectly scaled and the top-3 selection will be unreliable. If any weight value in the scoring_rules table is changed post-launch (for example during calibration based on LangSmith session data), this rule confirms the target sum that all four weight rules must collectively maintain.', 'Ranking Weight Factors Integrity Check', '1.0000', 'Root Cause Ranking Formula', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('19', '2026-07-12 06:13:20.138888+00', 'true', 'CONFIDENCE_CONTINUE_MAX', 'The overall session confidence score (sessions.overall_confidence_score, 0-100) below which the routing state stays "continue" — the outer-layer control loop keeps asking diagnostic questions rather than moving toward validation or report generation. This is the outer-layer session-level threshold, distinct from the inner-layer per-question Green/Amber/Red scoring in QUESTION_SCORE_RED and related rules. Below this threshold, signal is considered insufficient regardless of how many questions have been asked.', 'Continue Diagnosing — Upper Threshold', '60.0000', 'Confidence Scoring Model (Product Document)', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('20', '2026-07-12 06:13:20.138888+00', 'true', 'CONFIDENCE_VALIDATE_MIN', 'The overall session confidence score at or above which the routing state moves from "continue" to "validate". In this band the system has formed an emerging diagnosis and presents its hypothesis back to the founder to collect structured confirmation before proceeding further, rather than continuing to probe blindly.', 'Validate — Lower Threshold', '60.0000', 'Confidence Scoring Model (Product Document)', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('21', '2026-07-12 06:13:20.138888+00', 'true', 'CONFIDENCE_VALIDATE_MAX', 'The overall session confidence score below which the routing state remains "validate" rather than advancing to "generate_report". Between CONFIDENCE_VALIDATE_MIN and this value, the system is confirming its hypothesis with the founder rather than either continuing to probe or finalising the report.', 'Validate — Upper Threshold', '80.0000', 'Confidence Scoring Model (Product Document)', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('22', '2026-07-12 06:13:20.138888+00', 'true', 'CONFIDENCE_GENERATE_REPORT_MIN', 'The overall session confidence score at or above which the routing state becomes "generate_report" — sufficient confidence has been reached (via the inner-layer weighted root cause ranking) to produce the full Founder Clarity Report. This is the outer-layer completion trigger referenced in sessions.routing_state.', 'Generate Report — Threshold', '80.0000', 'Confidence Scoring Model (Product Document)', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('23', '2026-07-26 05:14:21.960253+00', 'true', 'CATEGORY_MAX_COMPUTED_PER_SESSION', 'The original Category-Level Aggregation spec hardcoded category max scores against the original 208-question bank (Idea 80, GTM 54, Sales 50, Product 50, Team 48, Fundraising 40, Operations 40, Psychology 54). The bank has since expanded to 330 questions, so those constants are stale. Category max must be computed at session time as (number of questions in scope for this founder in this category) x 2, because a founder only sees questions matching their stage group. Never hardcode those original max values — doing so causes the 30 percent CAT_RISK_THRESHOLD to fire far too early and flag categories that are not genuine problems.', 'Category Max Score Must Be Computed Per Session', '1.0000', 'Category-Level Aggregation (amended for expanded question bank)', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('24', '2026-07-26 05:14:21.960253+00', 'true', 'CATEGORY_CONFIRMED_CRITICAL', 'When every question asked within a category scores 2 (Red), so the category reaches its maximum possible score, that category is flagged Confirmed Critical. Its root causes receive the highest weight in the final ranking and the Founder Clarity Report leads with this category.', 'Category Confirmed Critical at Maximum Score', '1.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('25', '2026-07-26 05:14:21.960253+00', 'true', 'NO_CATEGORY_ABOVE_THRESHOLD_ACTION', 'When all 8 categories score below their 30 percent risk thresholds, no category is flagged as primary. The Agent must not force a diagnosis. The report should state that no single critical issue was identified and instead surface the 2 to 3 categories with the highest relative, though sub-threshold, scores as areas to monitor. This rule overrides any confidence-based routing that would otherwise generate a standard diagnostic report.', 'No Forced Diagnosis When All Categories Sub-Threshold', '0.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('26', '2026-07-26 05:14:21.960253+00', 'true', 'PSYCHOLOGY_NARRATIVE_PRECEDENCE', 'When the Founder Psychology category is flagged as primary alongside any business category, Founder Psychology always takes narrative precedence in the Founder Clarity Report, even when the business category carries a higher numerical score. This follows the Psychology Before Process design principle, Psychology Before Process. Numerical ranking still determines which root causes are surfaced; this rule governs report ordering and framing only.', 'Founder Psychology Takes Narrative Precedence', '1.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('27', '2026-07-26 05:14:21.960253+00', 'true', 'CATEGORY_THRESHOLD_SKIP_ACTION', 'When a Category Risk Score crosses the 30 percent threshold before all questions in that category have been asked, skip the remaining questions tagged Supplementary rather than Core, and proceed directly to 2 targeted deep-dive questions designed to confirm the specific root cause within that category. The rule value is the number of deep-dive questions to fire.', 'Skip Supplementary Questions on Threshold Crossing', '2.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('28', '2026-07-26 05:14:21.960253+00', 'true', 'CROSS_CATEGORY_ROOT_DRIVER_CHECK', 'When 2 or more categories are flagged as primary simultaneously, use the blind_spots table, which maps each business symptom to its underlying founder-psychology driver to test whether one category is the root driver of the other, rather than treating both as independent problems. For example, when Founder Psychology is flagged alongside Team, check whether founder behaviour signals suggest the team issue is downstream of founder behaviour. The rule value is the minimum number of simultaneously flagged categories that triggers this check.', 'Cross-Category Root Driver Test', '2.0000', 'Adaptive Branching Rules', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('29', '2026-07-26 05:14:21.960253+00', 'true', 'AMBIGUOUS_SCORE_DEFAULTS_HIGHER', 'If a founder answer is ambiguous between two score levels, the Agent defaults to the higher risk score and triggers a clarifying follow-up rather than guessing. Scores are never shown to the founder during the session — they are an internal diagnostic signal only, surfaced in aggregate form in the Founder Clarity Report.', 'Ambiguous Answers Default to Higher Risk', '1.0000', 'Question-Level Scoring Schema', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('30', '2026-07-26 05:14:21.960253+00', 'true', 'QUESTION_SCORED_ON_FIRST_ANSWER', 'Every question receives exactly one score per session, based on the founder first complete answer and not on a follow-up probe answer. Follow-up answers are scored separately and feed the branching logic rather than the original question score.', 'One Score Per Question, First Complete Answer Only', '1.0000', 'Question-Level Scoring Schema', '2026-07-26 05:28:45.98239+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('31', '2026-07-26 09:09:34.335459+00', 'true', 'PILLAR_SCORE_FROM_ANSWERS', 'Each of the six readiness pillars is scored 0-100 from the founder answers, via the existing chain questions.problem_id to problems.pillar_id to readiness_pillars.pillar_id. All 124 problems carry a pillar_id and none are null, so every scored answer rolls up to exactly one pillar. Method, in order. Step 1: score each answered question 0 Green, 1 Amber, 2 Red as normal. Step 2: for each pillar, sum the scores of the questions answered in that pillar, and divide by (number of questions actually answered in that pillar x 2) to give a pillar risk ratio between 0 and 1. Step 3: INVERT to convert risk into health, because question scores measure risk where higher is worse while pillar scores measure health where higher is better. pillar_score = round((1 - pillar_risk_ratio) x 100). A founder who scores Red on everything in a pillar gets a pillar score of 0, and all Green gets 100. Failing to invert produces exactly backwards results and is the most likely implementation error here. Step 4: map the resulting 0-100 value onto the score_bands defined on that pillar row. Only questions actually answered are counted in the denominator, never the full bank, for the same reason as CATEGORY_MAX_COMPUTED_PER_SESSION. If no questions were answered in a pillar, that pillar returns null rather than 0, and is excluded from the Business Health Score with the remaining weights renormalised to sum to 100.', 'Pillar Score Derivation From Founder Answers', '100.0000', 'Business Health Scoring Model', '2026-07-26 09:09:34.335459+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('32', '2026-07-26 09:09:34.335459+00', 'true', 'BUSINESS_HEALTH_SCORE_FORMULA', 'The overall Business Health Score is the weighted sum of the six pillar scores, using the pillar_weightage values on readiness_pillars which sum to exactly 100: Founder Readiness 25, Market Clarity 20, Revenue Maturity 20, Product and Execution 15, Team and Leadership 10, Strategic Clarity 10. Formula: business_health_score = sum over pillars of (pillar_score x pillar_weightage) / 100. Two behaviours that must not be missed. First, each pillar carries its own red_flag_threshold which fires independently of the overall score — a founder can hold a healthy overall number while Founder Readiness sits below 35, which triggers the Psychological State Note in the report regardless. The overall score must never suppress a pillar-level red flag. Second, pillar coverage is uneven by design: Market Clarity draws on 78 questions while Strategic Clarity draws on 35, so a Strategic Clarity score rests on fewer data points and should be treated as less reliable when few of its questions have been answered.', 'Overall Business Health Score', '100.0000', 'Business Health Scoring Model', '2026-07-26 09:09:34.335459+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('33', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_SCORE_METHODOLOGY', 'Produces sessions.overall_confidence_score (0-100), then bucketed by CONFIDENCE_CONTINUE_MAX, CONFIDENCE_VALIDATE_MIN/MAX and CONFIDENCE_GENERATE_REPORT_MIN. It answers "how certain are we that we have identified this founder''s real problem", never "how healthy is the business" — a failing business can carry a highly certain diagnosis, so Business Health must never feed this score. STRUCTURE: five weighted inputs describing what the evidence says, then two multipliers describing how much the evidence collection can be trusted. INPUTS, each normalised 0-1. (a) CATEGORY SIGNAL, weight from CONFIDENCE_WEIGHT_CATEGORY_SIGNAL — highest (category_risk_score / category_max) across the 8 categories, with category_max computed per session per CATEGORY_MAX_COMPUTED_PER_SESSION. Deliberately uses raw category risk rather than the root cause final score, because the final score already embeds confirmation status at 0.25 and using it alongside the confirmation input below would count confirmation twice. (b) EVIDENCE COVERAGE, weight from CONFIDENCE_WEIGHT_COVERAGE — questions answered divided by questions in scope for the founder''s stage group, capped at 1.0. (c) ANSWER CONSISTENCY, weight from CONFIDENCE_WEIGHT_CONSISTENCY — 1.0 when no contradictions are detected across the session, reduced as contradictions are found by the LLM layer. (d) CONFIRMATION RATIO, weight from CONFIDENCE_WEIGHT_CONFIRMATION — confirmation status of the top-ranked root causes mapped Confirmed 1.5, Unconfirmed 1.0, Not Tested 0.5 per CONFIRMATION_MULTIPLIER, rescaled to 0-1 by (value - 0.5) / 1.0. (e) SEPARATION, weight from CONFIDENCE_WEIGHT_SEPARATION — (top_root_cause_score - second_root_cause_score) / top_root_cause_score, capped at 1.0, set to 0 when the top score is 0 or the top two are tied. Guards against a decisive-sounding report built on a near-tie. CALCULATION: base = the five weighted inputs summed; then multiply by session_state_bands.reliability_factor for the founder''s current session state; then multiply by CONFIDENCE_STAGE_COHERENCE_FACTOR; then overall_confidence_score = round(base x reliability_factor x stage_coherence_factor x 100). The two multipliers are separated from the inputs on purpose — inputs measure what the evidence says, multipliers measure whether the evidence was gathered under conditions we can trust. Finally apply CONFIDENCE_HARD_RULES before routing on the number.', 'Overall Confidence Score — Derivation Method', '100.0000', 'Confidence Scoring Model (methodology defined internally — weights provisional pending product sign-off)', '2026-07-26 10:53:01.763771+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('34', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_WEIGHT_CATEGORY_SIGNAL', 'Weight applied to the strongest category risk signal when computing overall_confidence_score. Provisional value pending product sign-off. The four CONFIDENCE_WEIGHT_ rules must always sum to exactly 1.0000.', 'Confidence Weight — Category Signal Strength', '0.3000', 'Confidence Scoring Model (provisional)', '2026-07-26 10:52:34.517902+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('35', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_WEIGHT_CONFIRMATION', 'Weight applied to how thoroughly the leading root cause hypotheses have been confirmed rather than merely inferred. Provisional value pending product sign-off.', 'Confidence Weight — Confirmation Ratio', '0.1500', 'Confidence Scoring Model (provisional)', '2026-07-26 10:52:34.517902+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('36', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_WEIGHT_COVERAGE', 'Weight applied to the proportion of in-scope questions the founder has actually answered. Provisional value pending product sign-off.', 'Confidence Weight — Question Coverage', '0.2500', 'Confidence Scoring Model (provisional)', '2026-07-26 09:34:54.894584+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('37', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_WEIGHT_SEPARATION', 'Weight applied to the gap between the top-ranked and second-ranked root cause. Guards against the engine being confidently wrong when two candidates are near-tied, which would otherwise produce a decisive-sounding report on a coin flip. Provisional value pending product sign-off.', 'Confidence Weight — Top Root Cause Separation', '0.1000', 'Confidence Scoring Model (provisional)', '2026-07-26 10:52:34.517902+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('38', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_INTEGRITY_WEIGHTS_SUM', 'Integrity constraint. The five confidence weight rules (CONFIDENCE_WEIGHT_CATEGORY_SIGNAL, CONFIDENCE_WEIGHT_COVERAGE, CONFIDENCE_WEIGHT_CONSISTENCY, CONFIDENCE_WEIGHT_CONFIRMATION, CONFIDENCE_WEIGHT_SEPARATION) must sum to exactly 1.0000. Validate on load and fail closed if they do not, in the same way WEIGHT_FACTORS_SUM_CHECK guards the root cause ranking weights. Note this rule is deliberately NOT named with the CONFIDENCE_WEIGHT_ prefix, because underscore is a single-character wildcard in SQL LIKE, so a pattern of CONFIDENCE_WEIGHT_% would otherwise match this row too and return an inflated sum against perfectly valid data. Select the five weights by explicit list rather than by prefix.', 'Confidence Weights Integrity Check', '1.0000', 'Confidence Scoring Model', '2026-07-26 10:53:01.763771+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('39', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_MIN_QUESTIONS_FLOOR', 'Hard floor. Until at least this many questions have been answered in the session, overall_confidence_score is capped at 59 regardless of what the formula returns, which forces the continue route. Prevents a small number of strongly consistent early answers from triggering a full diagnostic report after three or four questions. Provisional value pending product sign-off.', 'Minimum Answered Questions Before Report', '12.0000', 'Confidence Scoring Model (provisional)', '2026-07-26 09:34:54.894584+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('40', '2026-07-26 09:34:54.894584+00', 'true', 'CONFIDENCE_HARD_RULES', 'Six conditions sit alongside the numeric score and are evaluated in this order, before routing. 1. DISTRESS OVERRIDE — if DISTRESS_QUESTIONS_TRIGGER is met or the session distress score reaches SESSION_STATE_HIGH_DISTRESS_THRESHOLD, the session leaves the confidence loop entirely and follows the distress path. It does not continue diagnosing and does not generate a standard report, whatever the score says. Wellbeing overrides diagnostic completeness in all cases. 2. SEVERE STAGE MISMATCH — if the evidence places the founder two or more stages away from the stage they self-reported, do not simply discount confidence via CONFIDENCE_STAGE_COHERENCE_FACTOR. Surface it to the founder and re-confirm their stage before generating any report, because the question set, root cause weights and tone were all selected from the wrong stage. 3. MINIMUM QUESTION FLOOR — see CONFIDENCE_MIN_QUESTIONS_FLOOR. generate_report is unreachable below it. 4. NO CATEGORY ABOVE THRESHOLD — if all 8 categories sit below their thresholds, do not force a diagnosis regardless of score; follow NO_CATEGORY_ABOVE_THRESHOLD_ACTION and report areas to monitor instead. 5. MULTI-CATEGORY CROSS-CHECK — if MULTI_CATEGORY_FLAG_THRESHOLD or more categories are flagged, the cross-check against stage and session state is mandatory before generate_report, even at 80 or above. 6. PSYCHOLOGY PRECEDENCE — if Founder Psychology is flagged, it leads the report narrative per PSYCHOLOGY_NARRATIVE_PRECEDENCE regardless of numerical ranking. The rule value is the number of hard rules.', 'Conditions That Override the Confidence Score', '6.0000', 'Confidence Scoring Model', '2026-07-26 10:53:01.763771+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('41', '2026-07-26 10:52:34.517902+00', 'true', 'CONFIDENCE_WEIGHT_CONSISTENCY', 'Weight applied to internal consistency of the founder answers when computing overall_confidence_score. Measures whether answers contradict each other — for example claiming recurring revenue in one answer while stating the product has never been sold in another. Contradictions mean at least one answer is unreliable, which lowers certainty in any diagnosis built on them. Detected by the LLM layer at session level rather than by predefined contradiction pairs, because the contradictions that matter are semantic rather than mechanical. Provisional value pending product sign-off.', 'Confidence Weight — Answer Consistency', '0.2000', 'Confidence Scoring Model (provisional)', '2026-07-26 10:52:34.517902+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('42', '2026-07-26 10:52:34.517902+00', 'true', 'CONFIDENCE_STAGE_COHERENCE_FACTOR', 'A multiplier on overall_confidence_score, not an input to it. The founder self-reports their stage during profile onboarding and it is stored on founders.stage_id. During diagnosis the answers may contradict that self-report — a founder who selects Growth/Scaling but shows no paying customers and no validated product is not at the stage they believe. This matters more than an ordinary weak signal, because the self-reported stage determines which questions were asked, which root cause weights were applied, and which tone prompt was used. If the stage was wrong, the entire session ran on false assumptions and confidence must reflect that. Multiplier values: evidence agrees with the self-reported stage 1.00; evidence suggests one stage away 0.90; evidence suggests two or more stages away 0.75. Assessment is written to stage_assessments with the confidence_score and assessment_basis columns recording the judgement and its reasoning. Provisional values pending product sign-off.', 'Stage Coherence Reliability Multiplier', '1.0000', 'Confidence Scoring Model (provisional)', '2026-07-26 10:52:34.517902+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('43', '2026-07-27 07:50:01.673096+00', 'true', 'CONFIDENCE_UNAVAILABLE_INPUT_HANDLING', 'Governs what happens when one of the five confidence inputs cannot be measured. RULE: an input that was not successfully measured is EXCLUDED from the weighted average, and the remaining weights are renormalised to sum to 1.0. It is never defaulted to 1.0 and never defaulted to 0. Defaulting to 1.0 awards full marks to a signal nobody checked, which can inflate the score by up to the weight of that input and push a session from validate into generate_report on evidence that does not exist. Defaulting to 0 penalises the founder for a gap in our tooling. Excluding it does neither, and matches PILLAR_SCORE_FROM_ANSWERS which already returns null for a pillar with no answers rather than scoring it zero. THREE DISTINCT STATES, do not conflate them. (1) The detector or calculation does not exist yet — exclude and renormalise. (2) It ran and found nothing wrong — that is a genuine measurement, score it 1.0. (3) It was attempted and failed, errored or timed out — exclude and renormalise, exactly as state 1. "We tried and could not check" is epistemically identical to "we did not check", so it must not be scored as a clean result. WORKED EXAMPLE with Answer Consistency unavailable: remaining weights sum to 0.80, so category signal becomes 0.30/0.80 = 0.375, coverage 0.25/0.80 = 0.3125, confirmation 0.15/0.80 = 0.1875, separation 0.10/0.80 = 0.125, summing to 1.0. GUARD: at least 3 of the 5 inputs must be measurable. Below that, cap overall_confidence_score at CONFIDENCE_CONTINUE_MAX and keep routing on continue, because a score renormalised onto one or two signals is not a confidence measure. The rule value is that minimum count. This rule applies to all five inputs, not only Answer Consistency.', 'Handling of Unmeasurable Confidence Inputs', '3.0000', 'Confidence Scoring Model', '2026-07-27 07:50:01.673096+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('44', '2026-07-27 08:56:09.747981+00', 'true', 'ROOT_CAUSE_MIN_DETECTION_CONFIDENCE', 'Detection focusing. A candidate root cause is admitted only when its detection_confidence (corroboration across ALL probes of the cause, greens included, 0-1) reaches this floor; weakly-corroborated single-signal causes are dropped before ranking. A CONFIRMED cause (double-red) is never dropped. Introduced after validation showed sessions surfacing up to 35 root causes. PROVISIONAL value pending product sign-off.', 'Root Cause Minimum Detection Confidence', '0.2000', 'Root Cause Ranking Formula (detection focusing — provisional)', '2026-07-27 08:56:09.747981+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('45', '2026-07-27 08:56:09.747981+00', 'true', 'ROOT_CAUSE_MAX_CANDIDATES', 'Detection focusing. After the confidence floor, keep at most this many candidate root causes (strongest first, by the engine ordering) before ranking. 0 disables the cap. Bounds the diagnostic set so ranking and the top-two separation signal are meaningful. PROVISIONAL value pending product sign-off.', 'Root Cause Maximum Candidates', '8.0000', 'Root Cause Ranking Formula (detection focusing — provisional)', '2026-07-27 08:56:09.747981+00') on conflict do nothing;
insert into "scoring_rules" ("rule_id", "created_at", "is_active", "rule_code", "rule_description", "rule_name", "rule_value", "source_document", "updated_at") values ('46', '2026-09-04 15:07:38.777962+00', 'true', 'MONITOR_MIN_COVERAGE', 'Fraction of the founder stage question budget that must be answered, with no category at or above CAT_RISK_THRESHOLD, before the diagnosis may stop and route to monitor instead of continuing to ask. The other half of NO_CATEGORY_ABOVE_THRESHOLD_ACTION, which says not to force a diagnosis when nothing is flagged but does not say when to stop. Set high on purpose: an all-clear is a stronger claim than a diagnosis because nothing downstream re-opens it, so it requires more evidence, not less. Read together with CONFIDENCE_MIN_QUESTIONS_FLOOR, which still applies -- whichever is greater wins.', 'Monitor Route - Minimum Coverage', '0.7500', 'Confidence Scoring Model', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
